import json, sys
g = json.load(open(sys.argv[1] + "/.dev-graph/state/graph.json", encoding="utf-8"))
print("top keys:", list(g.keys()))
nodes = g.get("nodes")
if isinstance(nodes, dict):
    items = list(nodes.items())
else:
    items = [(n.get("id"), n) for n in nodes]
print("node count:", len(items))
for k, n in items:
    print("---", k, n.get("kind"), n.get("title","")[:40])
    for f in ("feature_package_id","parent_feature","architecture_refs","implementation_readiness","evaluation_status","confirmation_status"):
        if f in n: print("   ", f, "=", n[f])
    sl = n.get("source_lineage")
    if sl: print("    source_lineage =", json.dumps(sl, ensure_ascii=False)[:300])
